"use client";
import * as React from "react";
import { cn } from "../lib/cn";
import { Slot } from "../lib/slot";

export interface BottomNavProps extends React.HTMLAttributes<HTMLElement> {
  /** Toont de balk ook op grote schermen; standaard alleen onder 860px. */
  always?: boolean;
  /** Houdt ruimte vrij voor de homebalk van iOS (standaard aan). */
  safeArea?: boolean;
}

/**
 * BottomNav — vaste navigatiebalk onderaan op mobiel.
 * Zet in je layout `padding-bottom` gelijk aan `var(--pxui-bottomnav-h)`,
 * zodat de laatste inhoud niet onder de balk verdwijnt.
 */
export const BottomNav = React.forwardRef<HTMLElement, BottomNavProps>(function BottomNav(
  { always, safeArea = true, className, children, ...rest },
  ref
) {
  return (
    <nav
      ref={ref}
      className={cn("pxui-bottomnav", className)}
      data-always={always ? "" : undefined}
      data-safe={safeArea ? "" : undefined}
      {...rest}
    >
      {children}
    </nav>
  );
});

export interface BottomNavItemProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  icon: React.ReactNode;
  active?: boolean;
  /** Telling of stip rechtsboven het icoon. `true` toont een stip. */
  badge?: React.ReactNode | true;
  asChild?: boolean;
}

export const BottomNavItem = React.forwardRef<HTMLButtonElement, BottomNavItemProps>(function BottomNavItem(
  { icon, active, badge, asChild, className, children, ...rest },
  ref
) {
  const Comp = (asChild ? Slot : "button") as React.ElementType;

  return (
    <Comp
      ref={ref}
      type={asChild ? undefined : "button"}
      aria-current={active ? "page" : undefined}
      data-active={active ? "" : undefined}
      className={cn("pxui-bottomnav-item", className)}
      {...rest}
    >
      <span className="pxui-bottomnav-icon">
        {icon}
        {badge !== undefined && badge !== false && (
          <span className={cn("pxui-bottomnav-badge", badge === true && "pxui-bottomnav-dot")}>
            {badge === true ? null : badge}
          </span>
        )}
      </span>
      <span className="pxui-bottomnav-label">{children}</span>
    </Comp>
  );
});

/* ============================ BottomNav ============================ */
.pxui-bottomnav {
  --pxui-bottomnav-h: 60px;
  position: fixed; inset-inline: 0; bottom: 0; z-index: 30;
  display: none; align-items: stretch;
  height: var(--pxui-bottomnav-h);
  background: color-mix(in srgb, var(--surface) 92%, transparent);
  backdrop-filter: blur(10px);
  border-top: 1px solid var(--border);
  box-shadow: 0 -2px 12px color-mix(in srgb, var(--text) 7%, transparent);
}
.pxui-bottomnav[data-safe] {
  height: calc(var(--pxui-bottomnav-h) + env(safe-area-inset-bottom, 0px));
  padding-bottom: env(safe-area-inset-bottom, 0px);
}
.pxui-bottomnav[data-always] { display: flex; }

@media (max-width: 860px) {
  .pxui-bottomnav { display: flex; }
}

.pxui-bottomnav-item {
  position: relative; flex: 1 1 0; min-width: 0;
  display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 3px;
  padding: 0 4px; border: 0; background: transparent; cursor: pointer;
  font-family: inherit; color: var(--text-3); text-decoration: none;
  transition: color var(--dur) var(--ease);
}
.pxui-bottomnav-item:hover { color: var(--text-2); }
.pxui-bottomnav-item[data-active] { color: var(--accent); }
.pxui-bottomnav-item:focus-visible { outline: 2px solid var(--accent); outline-offset: -3px; border-radius: var(--r-sm); }
.pxui-bottomnav-item::after {
  content: ""; position: absolute; top: 0; left: 50%; translate: -50% 0;
  width: 26px; height: 2px; border-radius: 0 0 var(--r-full) var(--r-full);
  background: var(--accent); opacity: 0;
  transition: opacity var(--dur) var(--ease);
}
.pxui-bottomnav-item[data-active]::after { opacity: 1; }

.pxui-bottomnav-icon { position: relative; display: grid; place-items: center; }
.pxui-bottomnav-label {
  font-size: 10px; font-weight: 700; letter-spacing: .01em;
  max-width: 100%; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}

.pxui-bottomnav-badge {
  position: absolute; top: -5px; left: calc(50% + 5px);
  display: grid; place-items: center; min-width: 16px; height: 16px; padding: 0 4px;
  border-radius: var(--r-full); background: var(--red); color: #fff;
  font-size: 9.5px; font-weight: 800; line-height: 1;
}
.pxui-bottomnav-dot { min-width: 8px; height: 8px; padding: 0; top: -1px; }
